import Select from '@jetbrains/ring-ui-built/components/select/select'

import useExistingVcsRootSelect from './ExistingVcsRootSelect.hooks'

type Props = {
  projectId?: string | null
  onVcsRootSelect?: (vcsRootId: string | null, name?: string, vcsName?: string) => void
  vcsRootId?: string
  createdRepositories?: Set<string>
}

function ExistingVcsRootSelect({
  projectId,
  vcsRootId,
  createdRepositories,
  onVcsRootSelect,
}: Props) {
  const {selectedItem, selectItems, handleSelect, handleFilter, areVcsRootsLoading, inputRef} =
    useExistingVcsRootSelect(projectId, vcsRootId, createdRepositories, onVcsRootSelect)

  return (
    <Select
      type={Select.Type.INPUT}
      size={Select.Size.FULL}
      data={selectItems}
      selected={selectedItem}
      loading={areVcsRootsLoading}
      label={''}
      filter={{fn: () => true}}
      onFilter={handleFilter}
      onSelect={handleSelect}
      inputPlaceholder={'Select VCS root'}
      loadingMessage={'Loading VCS roots...'}
      notFoundMessage={'No VCS roots found'}
      disabled={projectId == null}
      filterRef={inputRef}
      allowAny
      hideArrow
    />
  )
}

export default ExistingVcsRootSelect
