import Link from '@jetbrains/ring-ui-built/components/link/link'
import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import type React from 'react'

import {getExternalVcsRootEditUrl} from '../../../utils/vcs'

import {stringifyId} from 'src/types'

type Props = {
  vcsRootId?: string | null
  children?: React.ReactNode
}

const tooltipDelay = 50
const tooltipTopOffset = 10
const tooltipLeftOffset = 65

function EditVcsRootTooltip({vcsRootId, children}: Props) {
  return (
    <Tooltip
      delay={tooltipDelay}
      popupProps={{
        top: tooltipTopOffset,
        left: tooltipLeftOffset,
        directions: [Directions.TOP_CENTER],
      }}
      title={
        <>
          {'Modify '}
          <Link
            target="_blank"
            href={getExternalVcsRootEditUrl(stringifyId(vcsRootId))}
            rel="noreferrer"
          >
            {'the related VCS root'}
          </Link>
          {' to edit this setting'}
        </>
      }
    >
      {children}
    </Tooltip>
  )
}

export default EditVcsRootTooltip
