import Input, {Size} from '@jetbrains/ring-ui-built/components/input/input'
import type * as React from 'react'
import {useEffect, useRef} from 'react'

import Tooltip from '../../Tooltip/Tooltip'

type RepositoryNameInputProps = {
  value?: string
  disabled?: boolean
  disableReason?: string | null
  error?: string
  onChange: (event: React.ChangeEvent<HTMLInputElement>) => void
}

const focusWaitTimeOut = 300

function RepositoryNameInput({
  value = '',
  disabled,
  disableReason,
  error,
  onChange,
}: RepositoryNameInputProps) {
  const inputRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    setTimeout(() => {
      inputRef.current?.focus()
    }, focusWaitTimeOut)
  }, [])

  return (
    <Tooltip title={disabled ? disableReason : null}>
      <Input
        disabled={disabled}
        inputRef={inputRef}
        error={error}
        value={value}
        size={Size.FULL}
        placeholder={'Paste URL'}
        aria-label={'Pipeline repository name'}
        onChange={onChange}
        autoComplete="off"
      />
    </Tooltip>
  )
}

export default RepositoryNameInput
