import {useMemo} from 'react'

import type {VcsProvider} from '../../services/pipelinesApi.types'
import {loginToVcsProvider} from '../../utils/vcs'

import type {VcsProviderSelectItem} from './VcsProviderSelect.types'
import {getSelectVcsProvider} from './VcsProviderSelect.utils'

import type {ProjectId} from 'src/types'

export function useVcsProviderSelect(
  vcsProviders: VcsProvider[],
  selected?: VcsProvider | null,
  onSelectProvider?: (vcsProvider: VcsProvider) => void,
  onLogin?: () => void,
  projectId?: ProjectId,
) {
  const selectItems = useMemo(
    () =>
      vcsProviders.reduce<VcsProviderSelectItem[]>(getSelectVcsProvider(projectId, onLogin), []),
    [vcsProviders, projectId, onLogin],
  )
  const selectedItem = useMemo(
    () =>
      selectItems.find(vcsProvider => {
        const payload = vcsProvider.payload

        return selected?.connectionId != null
          ? payload.connectionId === selected.connectionId
          : payload.type === selected?.type
      }),
    [selected, selectItems],
  )
  const handleSelect = (newSelected: VcsProviderSelectItem | null) => {
    if (newSelected == null) {
      return
    }

    const {payload} = newSelected
    const {username, connectionId, type} = payload
    if (
      (connectionId != null && selected?.connectionId === connectionId) ||
      (connectionId == null && selected?.type === type)
    ) {
      return
    }

    if (username == null && connectionId != null) {
      loginToVcsProvider(connectionId, projectId, onLogin)
    }

    onSelectProvider?.(payload)
  }

  return {selectedItem, selectItems, handleSelect}
}
