import Input, {Size} from '@jetbrains/ring-ui-built/components/input/input'
import classNames from 'classnames'
import type React from 'react'
import Skeleton from 'react-loading-skeleton'

import SkeletonLoaderTheme from '../../../../../common/SkeletonLoaderTheme/SkeletonLoaderTheme'
import {getIsGitVcsRoot} from '../../../utils/getIsGitVcsRoot'
import BranchSpecificationSelect from '../../BranchSpecificationSelect/BranchSpecificationSelect'
import DefaultBranchSelect from '../../DefaultBranchSelect/DefaultBranchSelect'
import SlideInOutAnimation from '../../SlideInOutAnimation/SlideInOutAnimation'
import EditVcsRootTooltip from '../EditVcsRootTooltip/EditVcsRootTooltip'

import {useExistingVcsRootForm} from './ExistingVcsRootForm.hooks'

import styles from './ExistingVcsRootForm.module.css'

type Props = {
  vcsRootId?: string | null
  vcsName?: string | null
  children?: React.ReactNode
  compact?: boolean
}
function ExistingVcsRootForm({vcsRootId, vcsName, compact, children}: Props) {
  const {url, port, branch, branchSpecification, isLoading} = useExistingVcsRootForm(vcsRootId)
  const isGitVcsRoot = getIsGitVcsRoot(vcsName)
  const showVcsRootInfo = url != null || port != null

  const form = (
    <div className={classNames(styles.form, {[styles.compact]: compact})}>
      {url && (
        <>
          <label className={classNames({[styles.labelCompact]: compact})}>{'URL'}</label>
          <Input value={url} size={Size.FULL} disabled />
        </>
      )}
      {port && (
        <>
          <label className={classNames({[styles.labelCompact]: compact})}>{'Port'}</label>
          <Input value={port} size={Size.FULL} disabled />
        </>
      )}
      {isGitVcsRoot && (
        <>
          <label className={classNames({[styles.labelCompact]: compact})}>{'Default branch'}</label>
          <DefaultBranchSelect selected={branch} disabled />
          <label className={classNames({[styles.labelCompact]: compact}, styles.branches)}>
            {'Branches to monitor'}
          </label>
          <BranchSpecificationSelect
            specification={branchSpecification ?? ''}
            defaultBranch={branch}
            disabled
          />
        </>
      )}
    </div>
  )

  return (
    <SlideInOutAnimation show={vcsRootId != null} mountOnEnter unmountOnExit>
      {isLoading ? (
        <SkeletonLoader isGitVcsRoot={getIsGitVcsRoot(vcsName)} compact={compact} />
      ) : (
        <>
          {showVcsRootInfo &&
            (compact ? (
              form
            ) : (
              <EditVcsRootTooltip vcsRootId={vcsRootId}>{form}</EditVcsRootTooltip>
            ))}
          {children}
        </>
      )}
    </SlideInOutAnimation>
  )
}

type SkeletonLoaderProps = {
  isGitVcsRoot?: boolean
  compact?: boolean
}

const width = 180
const height = 24
const compactHeight = 20

function SkeletonLoader({compact, isGitVcsRoot}: SkeletonLoaderProps) {
  const renderRow = () => (
    <>
      <Skeleton
        className={classNames({[styles.labelCompact]: compact})}
        width={width}
        height={compact ? compactHeight : height}
      />
      <Skeleton height={height} />
    </>
  )

  return (
    <SkeletonLoaderTheme borderRadius={4}>
      <div className={classNames(styles.form, {[styles.compact]: compact})}>
        {renderRow()}
        {isGitVcsRoot && (
          <>
            {renderRow()}
            {renderRow()}
          </>
        )}
        {!compact && renderRow()}
      </div>
    </SkeletonLoaderTheme>
  )
}

export default ExistingVcsRootForm
