import eyeIcon from '@jetbrains/icons/eye'
import eyeCrossedIcon from '@jetbrains/icons/eye-crossed'
import type {InputAttrs} from '@jetbrains/ring-ui-built/components/input/input'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import cn from 'classnames'
import {memo, useState} from 'react'

import Input from '../Input'

import styles from './PasswordInput.module.css'

type PasswordInputProps = InputAttrs & {showEyeButton?: boolean}

function PasswordInput({inputClassName, showEyeButton = true, ...props}: PasswordInputProps) {
  const [isShowPassword, setIsShowPassword] = useState(false)
  const isImitatePassword = !isShowPassword || undefined
  const iconButtonTitle = `${isShowPassword ? 'Hide' : 'Show'} password`
  const iconButtonClickHandler = () => setIsShowPassword(!isShowPassword)
  const iconButtonIcon = isShowPassword ? eyeIcon : eyeCrossedIcon
  const finalInputClassName = cn(styles.input, inputClassName)

  return (
    <Input
      inputClassName={finalInputClassName}
      {...props}
      afterInput={
        showEyeButton && (
          <IconButton
            className={styles.eyeButton}
            onClick={iconButtonClickHandler}
            icon={iconButtonIcon}
            title={iconButtonTitle}
          />
        )
      }
      data-imitate-password={isImitatePassword}
    />
  )
}

export default memo(PasswordInput)
