import Button from '@jetbrains/ring-ui-built/components/button/button'
import ButtonGroup from '@jetbrains/ring-ui-built/components/button-group/button-group'
import Link from '@jetbrains/ring-ui-built/components/link/link'
import Radio from '@jetbrains/ring-ui-built/components/radio/radio'
import Toggle from '@jetbrains/ring-ui-built/components/toggle/toggle'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import {memo} from 'react'

import {isPullRequestsFeatureEnabled} from '../../utils/featureToggles'
import Input, {Size} from '../Input'
import SlideInOutAnimation from '../SlideInOutAnimation/SlideInOutAnimation'

import {BranchSpecificationPolicy, branchSpecDocLink} from './BranchSpecificationSelect.consts'
import {useBranchSpecificationSelect} from './BranchSpecificationSelect.hooks'

import styles from './BranchSpecificationSelect.module.css'

type Props = {
  groupClassName?: string
  specification: string
  defaultBranch?: string | null
  isBranchesEnabled?: boolean
  isPullRequestsEnabled?: boolean
  allBranches?: string
  disabled?: boolean
  isBranchesToggleSupported?: boolean
  isPullRequestsSupported?: boolean
  onSelectSpecification?: (spec: string) => void
  onToggleBranches?: (value: boolean) => void
  onTogglePullRequests?: (value: boolean) => void
}
function BranchSpecificationSelect({
  groupClassName,
  specification,
  defaultBranch,
  allBranches,
  isBranchesEnabled,
  isPullRequestsEnabled,
  isBranchesToggleSupported,
  disabled,
  isPullRequestsSupported,
  onSelectSpecification,
  onToggleBranches,
  onTogglePullRequests,
}: Props) {
  const {
    specificationPolicy,
    handleChangePolicy,
    shouldShowExamples,
    handleShowExamples,
    specificationInputValue,
    handleSpecificationInputChange,
    handleToggleBranches,
    handleTogglePullRequests,
  } = useBranchSpecificationSelect(
    specification,
    defaultBranch,
    allBranches,
    disabled,
    onSelectSpecification,
    onToggleBranches,
    onTogglePullRequests,
  )

  return (
    <div>
      {isPullRequestsFeatureEnabled ? (
        <div className={styles.wrapper}>
          {isBranchesToggleSupported && (
            <Toggle disabled={disabled} checked={isBranchesEnabled} onChange={handleToggleBranches}>
              {'Branches'}
            </Toggle>
          )}
          <ButtonGroup className={classNames(styles.branches, groupClassName)}>
            <Button
              className={styles.item}
              disabled={disabled || (isBranchesToggleSupported && !isBranchesEnabled)}
              active={specificationPolicy === BranchSpecificationPolicy.ALL_BRANCHES}
              onClick={() => handleChangePolicy(BranchSpecificationPolicy.ALL_BRANCHES)}
            >
              {'All'}
            </Button>
            <Button
              className={styles.item}
              disabled={disabled || (isBranchesToggleSupported && !isBranchesEnabled)}
              active={specificationPolicy === BranchSpecificationPolicy.DEFAULT_ONLY}
              onClick={() => handleChangePolicy(BranchSpecificationPolicy.DEFAULT_ONLY)}
            >
              {'Default branch'}
            </Button>
            <Button
              className={styles.item}
              disabled={disabled || (isBranchesToggleSupported && !isBranchesEnabled)}
              active={specificationPolicy === BranchSpecificationPolicy.SPECIFIC}
              onClick={() => handleChangePolicy(BranchSpecificationPolicy.SPECIFIC)}
            >
              {'Specific'}
            </Button>
          </ButtonGroup>
        </div>
      ) : (
        <Radio
          className={groupClassName}
          value={specificationPolicy}
          onChange={handleChangePolicy}
          disabled={disabled}
        >
          <Radio.Item value={BranchSpecificationPolicy.ALL_BRANCHES}>{'All branches'}</Radio.Item>
          <Radio.Item value={BranchSpecificationPolicy.DEFAULT_ONLY}>
            {'Only default branch'}
          </Radio.Item>
          <Radio.Item value={BranchSpecificationPolicy.SPECIFIC}>{'Specific branches'}</Radio.Item>
        </Radio>
      )}
      <SlideInOutAnimation
        show={specificationPolicy === BranchSpecificationPolicy.SPECIFIC}
        mountOnEnter
        unmountOnExit
      >
        <Input
          className={styles.specInputContainer}
          inputClassName={styles.specInput}
          size={Size.FULL}
          value={specificationInputValue}
          onChange={handleSpecificationInputChange}
          label={'Branch specification'}
          multiline
          disabled={disabled}
        />
        <div className={styles.help}>
          {'Read more about '}
          <Link href={branchSpecDocLink} target="_blank" rel="noreferrer">
            {'Branch specification'}
          </Link>
          {' or '}
          <IconButton
            className={styles.showExamples}
            iconClassName={styles.icon}
            icon={shouldShowExamples ? 'chevron-down' : 'chevron-right'}
            onClick={handleShowExamples}
            childrenLeft
            inline
          >
            {'Show examples'}
          </IconButton>
        </div>
        <SlideInOutAnimation show={shouldShowExamples}>
          <div className={classNames(styles.examples)}>
            <div>
              <span className={styles.tag}>{'-:<default>'}</span>
              {' - excludes the default branch'}
            </div>
            <div>
              <span className={styles.tag}>{'+:refs/tags/*'}</span>
              {' - includes all tags'}
            </div>
            <div>
              <span className={styles.tag}>{'+:refs/heads/main'}</span>
              {' - includes main branch'}
            </div>
            <div>
              <span className={styles.tag}>{'+:refs/heads/dev/*'}</span>
              {
                ' - includes all branches whose names start with dev/. Branches do not show their shared dev/ prefix in the UI'
              }
            </div>
            <div>
              <span className={styles.tag}>{'+:refs/heads/(dev/*)'}</span>
              {
                ' - includes all branches whose names start with dev/. Branches show their full names in the UI'
              }
            </div>
          </div>
        </SlideInOutAnimation>
      </SlideInOutAnimation>
      {isPullRequestsFeatureEnabled && isPullRequestsSupported && (
        <Toggle
          className={styles.pullRequestsToggle}
          checked={isPullRequestsEnabled}
          onChange={handleTogglePullRequests}
        >
          {'Pull requests'}
        </Toggle>
      )}
    </div>
  )
}

export default memo(BranchSpecificationSelect)
