import ExceptionEmptyIcon from '@jetbrains/icons/exception-empty-12px.svg'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import ButtonSet from '@jetbrains/ring-ui-built/components/button-set/button-set'
import Collapse from '@jetbrains/ring-ui-built/components/collapse/collapse'
import CollapseContent from '@jetbrains/ring-ui-built/components/collapse/collapse-content'
import CollapseControl from '@jetbrains/ring-ui-built/components/collapse/collapse-control'
import {ControlsHeight} from '@jetbrains/ring-ui-built/components/global/controls-height'
import {Fragment} from 'react'

import {getPipelinesHref} from '../../../../../../routes'
import {RouterButton} from '../../../../../common/RouterLink/RouterLink'
import styles from '../VcsAnyRepositoryAuthenticationForm.module.css'

type VcsRepositoryAuthenticationFormFooterProps = {
  compact?: boolean
  onClick: (event: React.FormEvent<HTMLButtonElement>) => void
  loading?: boolean
  disabled?: boolean
  errorMessage?: string
  cancelButton?: React.ReactNode
}

const maxErrorMessageLength = 130
const errorMessageTextHeight = 42

function VcsRepositoryAuthenticationFormFooter({
  compact,
  onClick,
  loading,
  disabled,
  errorMessage,
  cancelButton,
}: VcsRepositoryAuthenticationFormFooterProps) {
  const isErrorMessageLarge = errorMessage?.length && errorMessage?.length > maxErrorMessageLength
  const minErrorMessageTextnHeight = isErrorMessageLarge ? errorMessageTextHeight : undefined
  const cancelLink = getPipelinesHref()
  const buttonLabel = compact ? 'Test connection' : 'Proceed'

  return (
    <div className={styles.buttonFooter}>
      <ButtonSet>
        <Button
          onClick={onClick}
          inline={compact}
          type="submit"
          loader={loading}
          disabled={disabled}
          primary
          className={styles.proceedButton}
          height={ControlsHeight.M}
        >
          {buttonLabel}
        </Button>
        {cancelButton ? (
          cancelButton
        ) : (
          <>
            {!compact && (
              <RouterButton to={cancelLink} height={ControlsHeight.M}>
                {'Cancel'}
              </RouterButton>
            )}
          </>
        )}
      </ButtonSet>
      {errorMessage?.length && (
        <div className={styles.errorMessage}>
          <div className={styles.errorMessageIcon}>
            <ExceptionEmptyIcon />
          </div>
          <Collapse className={styles.errorMessageText}>
            {isErrorMessageLarge ? (
              <Fragment>
                <CollapseContent minHeight={minErrorMessageTextnHeight}>
                  {errorMessage}
                </CollapseContent>
                <CollapseControl>
                  {(collapsed: boolean) => (
                    <Button inline>{collapsed ? 'View details' : 'Hide details'}</Button>
                  )}
                </CollapseControl>
              </Fragment>
            ) : (
              errorMessage
            )}
          </Collapse>
        </div>
      )}
    </div>
  )
}

export default VcsRepositoryAuthenticationFormFooter
