import {graphql} from 'react-relay'

export const createPipelinePageQuery = graphql`
  query CreatePipelinePageQuery($locator: String!, $skip: Boolean = false) {
    project(projectLocator: $locator) @skip(if: $skip) {
      vcsRoots {
        count
      }
      ancestorProjects {
        project {
          vcsRoots {
            count
          }
        }
      }
    }
  }
`
