import {graphql} from 'react-relay'

export const existingVcsRootFormQuery = graphql`
  query ExistingVcsRootFormQuery($vcsRootLocator: String!) {
    vcsRoots(locator: $vcsRootLocator) {
      vcsRoot {
        properties {
          property {
            name
            value
          }
        }
      }
    }
  }
`
