import Button from '@jetbrains/ring-ui-built/components/button/button'
import Dialog from '@jetbrains/ring-ui-built/components/dialog/dialog'
import {Size} from '@jetbrains/ring-ui-built/components/input/input'
import {Content, Header} from '@jetbrains/ring-ui-built/components/island/island'
import Panel from '@jetbrains/ring-ui-built/components/panel/panel'
import Upload from '@jetbrains/ring-ui-built/components/upload/upload'

import type {ProjectId} from '../../../../../../../types'
import Input from '../../../Input'

import useVcsSshUploadDialog from './useVcsSshUploadDialog'

import styles from './VcsSshUploadDialog.module.css'

type VcsSshUploadDialogProps = {
  projectId: ProjectId
  onClose: (keyName?: string) => void
}

const dialogTitle = 'Upload SSH key'

function VcsSshUploadDialog({projectId, onClose}: VcsSshUploadDialogProps) {
  const {
    sshKeyName,
    errorMessage,
    isSshKeyUploading,
    isDisabledUploadButton,
    clickUploadSshKeyButtonHandler,
    changeSshKeyNameInputHandler,
    filesSelectedUploadHandler,
    closeDialogHandler,
  } = useVcsSshUploadDialog(projectId, onClose)

  return (
    <Dialog
      show
      trapFocus
      showCloseButton
      closeButtonInside
      onCloseAttempt={closeDialogHandler}
      label={dialogTitle}
    >
      <Header>{dialogTitle}</Header>
      <Content>
        <Upload className={styles.uploadButton} onFilesSelected={filesSelectedUploadHandler}>
          {'Browse or drop private key to upload'}
        </Upload>
        <Input
          label="Key name"
          value={sshKeyName}
          size={Size.FULL}
          onChange={changeSshKeyNameInputHandler}
        />
      </Content>
      {errorMessage && <div className={styles.errorMessage}>{errorMessage}</div>}
      <Panel>
        <Button
          primary
          title="Upload"
          loader={isSshKeyUploading}
          disabled={isDisabledUploadButton}
          onClick={clickUploadSshKeyButtonHandler}
        >
          {'Upload'}
        </Button>
        <Button disabled={isSshKeyUploading} title="Close" onClick={closeDialogHandler}>
          {'Close'}
        </Button>
      </Panel>
    </Dialog>
  )
}

export default VcsSshUploadDialog
