import {emptyObject} from '../../../../utils/empty'
import type {VcsProvider} from '../services/pipelinesApi.types'
import {VcsProviderType} from '../services/pipelinesApi.types'

import {vcsAnyGitProvider} from './CreatePipelinePage.consts'

export function getAuthorizedVcsProvider(vcsProviders: VcsProvider[]) {
  return vcsProviders.find(provider => provider.username != null) ?? null
}

export function getPreselectedVcsProvider(
  vcsProviders: VcsProvider[] | null,
  isSelectedAnyProvider?: boolean,
): VcsProvider {
  let existingVcsRootProvider = emptyObject

  if (isSelectedAnyProvider) {
    return vcsAnyGitProvider
  }

  if (vcsProviders) {
    for (const provider of vcsProviders) {
      if (provider?.connectionId) {
        return provider
      }
      if (provider?.type === VcsProviderType.EXISTING_VCS_ROOT) {
        existingVcsRootProvider = provider
      }
    }
  }

  return existingVcsRootProvider
}
