import {generateFreeName} from '../../utils/generateFreeName'
import {capitalizeFirstLetter} from '../../utils/string'
import {ProtocolVcsRepository} from '../VcsAnyRepositoryAuthenticationForm/VcsAnyRepositoryAuthenticationForm.consts'

export function getGuessedGitProtocol(url?: string) {
  const gitPrefix = 'git@'

  if (url?.startsWith(ProtocolVcsRepository.HTTPS.toLocaleLowerCase())) {
    return ProtocolVcsRepository.HTTPS
  } else if (
    url?.startsWith(ProtocolVcsRepository.SSH.toLocaleLowerCase()) ||
    url?.startsWith(gitPrefix)
  ) {
    return ProtocolVcsRepository.SSH
  }

  return null
}

function getPipelineNameByRepositoryName(name: string): string {
  return name.split(/[-_]/g).map(capitalizeFirstLetter).join(' ')
}

export function generatePipelineName(repositoryName: string, pipelineNames: string[]) {
  const name = getPipelineNameByRepositoryName(repositoryName)
  return generateFreeName({
    getName: iteration => (iteration === 0 ? name : `${name} ${iteration}`),
    usedNames: pipelineNames,
    errorMessage: 'Error while generating new pipeline name',
  })
}
