import {getExtractErrorMessages} from '../../EditPipelinePage/EditPipelinePage.utils'
import {pipelinesApi} from '../../services/pipelinesApi'

function useRepositoryTestConnection() {
  const [
    repositoryTestConnection,
    {
      isRepositoryTestConnectionOK,
      repositoryTestConnectionError,
      isRepositoryTestConnectionError,
      isRepositoryTestConnectionLoading,
      reset: repositoryTestConnectionReset,
    },
  ] = pipelinesApi.endpoints.repositoryTestConnection.useMutation({
    selectFromResult: ({data, error, isLoading}) => {
      const extractedServerError = getExtractErrorMessages(error)
      const repositoryTestConnectionError = data?.errors || extractedServerError

      return {
        repositoryTestConnectionError,
        isRepositoryTestConnectionOK: data?.status === 'OK',
        isRepositoryTestConnectionError: !!error || data?.status === 'ERROR',
        isRepositoryTestConnectionLoading: isLoading,
      }
    },
  })

  return {
    isRepositoryTestConnectionOK,
    repositoryTestConnectionError,
    isRepositoryTestConnectionError,
    isRepositoryTestConnectionLoading,
    repositoryTestConnection,
    repositoryTestConnectionReset,
  }
}

export default useRepositoryTestConnection
