import type {SelectItem} from '@jetbrains/ring-ui-built/components/select/select'
import {useEffect, useMemo, useRef, useState} from 'react'

import type {ExistingVcsRootSelectQuery} from './__generated__/ExistingVcsRootSelectQuery.graphql'
import {query} from './ExistingVcsRootSelect.queries'
import {getFilteredVcsRootSelectItems, getVcsRootSelectItems} from './ExistingVcsRootSelect.utils'

import {useBackgroundQuery} from 'src/hooks/relay/useBackgroundQuery'

export default function useExistingVcsRootSelect(
  parentProjectId?: string | null,
  vcsRootId?: string,
  createdRepositories?: Set<string>,
  onVcsRootSelect?: (vcsRootId: string | null, name?: string, vcsName?: string) => void,
) {
  const [filter, setFilter] = useState('')
  const inputRef = useRef<HTMLInputElement>(null)
  const [{data, isLoading}, fetchVcsRoots] = useBackgroundQuery<ExistingVcsRootSelectQuery>(query)

  useEffect(() => {
    if (parentProjectId != null) {
      fetchVcsRoots({projectLocator: `id:${parentProjectId}`}, true)
    }
  }, [parentProjectId, fetchVcsRoots])

  useEffect(() => {
    if (!vcsRootId) {
      requestAnimationFrame(() => {
        inputRef.current?.focus()
        inputRef.current?.click()
      })
    }
  }, [vcsRootId])

  const handleFilter = (value: string) => {
    setFilter(value)
    onVcsRootSelect?.(null)
  }
  const selectItems = useMemo(
    () => getVcsRootSelectItems(data, createdRepositories),
    [createdRepositories, data],
  )
  const selectedItem = selectItems.find(item => item.key === vcsRootId)
  const handleSelect = (newSelected: SelectItem<{vcsName?: string | null}> | null) => {
    const {key, label, vcsName} = newSelected ?? {}

    if (key && typeof key !== 'number') {
      onVcsRootSelect?.(`${key}`, `${label}`, `${vcsName}`)
      setFilter('')
    }
  }

  const filteredItems = useMemo(
    () => getFilteredVcsRootSelectItems(selectItems, filter),
    [selectItems, filter],
  )

  return {
    selectedItem,
    areVcsRootsLoading: isLoading,
    selectItems: filteredItems,
    inputRef,
    handleSelect,
    handleFilter,
  }
}
