import Button from '@jetbrains/ring-ui-built/components/button/button'
import {Size} from '@jetbrains/ring-ui-built/components/input/input'
import Select from '@jetbrains/ring-ui-built/components/select/select'
import classNames from 'classnames'
import {Fragment} from 'react'

import PasswordInput from '../../PasswordInput/PasswordInput'
import formStyles from '../VcsAnyRepositoryAuthenticationForm.module.css'

import useVcsSshRepositoryAuthenticationForm from './useVcsSshRepositoryAuthenticationForm'
import type {
  SelectItemVcsSsh,
  VcsSshRepositoryAuthenticationFormProps,
} from './VcsSshRepositoryAuthenticationForm.types'
import VcsSshUploadDialog from './VcsSshUploadDialog/VcsSshUploadDialog'

import styles from './VcsSshRepositoryAuthenticationForm.module.css'

function VcsSshRepositoryAuthenticationForm({
  projectId,
  keyName,
  passphrase,
  onSelectKeyName,
  onChangePassphrase,
}: VcsSshRepositoryAuthenticationFormProps) {
  const {
    isProjectSshKeysLoading,
    projectSshKeysSelectItems,
    projectSshKeysSelectedValue,
    isShowSshUploadDialog,
    selectDropdownFilterOptions,
    clockUploadDialogOpenButtonHandler,
    clickUploadDialogCloseButtonHandler,
  } = useVcsSshRepositoryAuthenticationForm(projectId, keyName, onSelectKeyName)
  const encrypted = projectSshKeysSelectedValue?.encrypted
  const hasProjectSshKeysSelectItems = !!projectSshKeysSelectItems.length

  return (
    <Fragment>
      <div className={formStyles.inputGropup}>
        <div className={formStyles.inputGropupLabel}>{'SSH key'}</div>
        <div className={classNames(formStyles.inputGropupControl, styles.inputGropupControlRow)}>
          {hasProjectSshKeysSelectItems && (
            <Fragment>
              <div className={styles.select}>
                <Select<SelectItemVcsSsh>
                  data={projectSshKeysSelectItems}
                  loading={isProjectSshKeysLoading}
                  loadingMessage={'Loading ssh keys...'}
                  size={Select.Size.FULL}
                  label="Select existing"
                  selected={projectSshKeysSelectedValue}
                  filter={selectDropdownFilterOptions}
                  onSelect={onSelectKeyName}
                />
              </div>

              <span className={styles.inputGropupControlRowMiddle}>{'or'}</span>
            </Fragment>
          )}
          <Button onClick={clockUploadDialogOpenButtonHandler}>{'Upload SSH Key'}</Button>
          {isShowSshUploadDialog && (
            <VcsSshUploadDialog
              projectId={projectId}
              onClose={clickUploadDialogCloseButtonHandler}
            />
          )}
        </div>
      </div>
      {encrypted && (
        <div className={formStyles.inputGropup}>
          <label htmlFor="access-token-input" className={formStyles.inputGropupLabel}>
            {'Passphrase'}
          </label>
          <div className={formStyles.inputGropupControl}>
            <PasswordInput
              key={keyName}
              onChange={onChangePassphrase}
              value={passphrase}
              name="passphrase"
              data-imitate-password
              autoComplete="off"
              id="ssh-passphrase"
              size={Size.FULL}
              showEyeButton={!!passphrase}
            />
          </div>
        </div>
      )}
    </Fragment>
  )
}

export default VcsSshRepositoryAuthenticationForm
