import {baseUri} from '@jetbrains/teamcity-ui'
import type {QueryParams} from '@jetbrains/teamcity-ui/dist/utils'
import {resolveRelative} from '@jetbrains/teamcity-ui/dist/utils'

import {getAccountRootProjectId} from '../PipelinesPages.consts'
import type {VcsRootDto} from '../services/pipelinesApi.types'

import type {ProjectId} from 'src/types'

const gitSuffix = '.git'
function getTruncatedUrl(url: string) {
  return url.endsWith(gitSuffix) ? url.slice(0, url.length - gitSuffix.length) : url
}

const sshGitRepoRegex = /^git@([\w.-]+):(.*)$/
export function getRepositoryFullName(repositoryUrl: string) {
  const truncatedUrl = getTruncatedUrl(repositoryUrl)

  if (truncatedUrl.startsWith('http')) {
    try {
      const {pathname} = new URL(truncatedUrl)

      return pathname.slice(1)
    } catch {
      return truncatedUrl
    }
  }

  const match = truncatedUrl.match(sshGitRepoRegex)

  return match == null ? truncatedUrl : match[2]
}

export function getRepositoryNameFromVcsRoot(vcsRoot: VcsRootDto, isMain?: boolean) {
  return vcsRoot.isExternal
    ? vcsRoot.name!
    : isMain
      ? vcsRoot.vcsProviderType != null
        ? getRepositoryFullName(vcsRoot.url)
        : vcsRoot.url
      : vcsRoot.url.replace(/^https?:\/\//, '')
}

export function getHttpsRepositoryUrlFromSsh(repositoryUrl: string) {
  const truncatedUrl = getTruncatedUrl(repositoryUrl)

  const match = truncatedUrl.match(sshGitRepoRegex)

  return match == null ? truncatedUrl : `https://${match[1]}/${match[2]}`
}

export function verifyRepositoryUrl(repositoryUrl: string) {
  try {
    const url = new URL(repositoryUrl)
    return url.pathname.length > 1
  } catch {
    return false
  }
}

export function getVcsProviderLoginUrl(
  connectionId: string,
  projectId = getAccountRootProjectId(),
) {
  return `${baseUri}/app/pipeline/provider/auth/${connectionId}/login?externalProjectId=${projectId}`
}

const TIMEOUT = 1000
export function loginToVcsProvider(
  connectionId: string,
  projectId?: ProjectId,
  onLogin?: () => void,
) {
  const win = window.BS?.Util?.popupWindow(
    getVcsProviderLoginUrl(connectionId, projectId),
    `vcs_${connectionId}`,
    {
      safe: false,
    },
  )
  const interval = window.setInterval(() => {
    if (win == null || win.closed) {
      window.clearInterval(interval)
      onLogin?.()
    }
  }, TIMEOUT)
}

export function getExternalVcsRootEditUrl(
  vcsRootId?: string,
  action = 'editVcsRoot',
  params?: QueryParams,
  cameFromUrl: string | null = location.href,
) {
  return resolveRelative('/admin/editVcsRoot.html', {
    init: '1',
    action,
    vcsRootId,
    cameFromUrl,
    ...params,
  })
}
