import Radio from '@jetbrains/ring-ui-built/components/radio/radio'
import cn from 'classnames'

import SlideInOutAnimation from '../SlideInOutAnimation/SlideInOutAnimation'

import useVcsAnyRepositoryAuthenticationForm from './useVcsAnyRepositoryAuthenticationForm'
import {
  HttpsRepositoryAuthType,
  ProtocolVcsRepository,
  vcsAnyRepositoryProtocols,
} from './VcsAnyRepositoryAuthenticationForm.consts'
import type {VcsAnyRepositoryAuthenticationFormProps} from './VcsAnyRepositoryAuthenticationForm.types'
import VcsHttpsRepositoryAuthenticationForm from './VcsHttpsRepositoryAuthenticationForm/VcsHttpsRepositoryAuthenticationForm'
import VcsRepositoryAuthenticationFormFooter from './VcsRepositoryAuthenticationFormFooter/VcsRepositoryAuthenticationFormFooter'
import VcsSshRepositoryAuthenticationForm from './VcsSshRepositoryAuthenticationForm/VcsSshRepositoryAuthenticationForm'

import styles from './VcsAnyRepositoryAuthenticationForm.module.css'

function VcsAnyRepositoryAuthenticationForm({
  projectId,
  url,
  vcsProtocol,
  onChangeVcsProtocol,
  httpsAuthType = HttpsRepositoryAuthType.TOKEN,
  onChangeHttpsAuthType,
  onSumbit,
  username = '',
  password = '',
  disableChangingVcsProtocol,
  compact,
  cancelButton,
}: VcsAnyRepositoryAuthenticationFormProps) {
  const {
    testConnectionErrorMessage,
    isRepositoryTestConnectionError,
    isProceedButtonDisabled,
    isShowVcsAnyRepositoryForm,
    isRepositoryTestConnectionLoading,
    httpsAuthenticationFormError,
    httpsAuthenticationUserCredentials,
    sshAuthenticationUserCredentials,
    changeSshAuthenticationKeyNameSelectHandle,
    changeSshAuthenticationPassphraseInputHandler,
    changeHttpsAuthenticationAuthTypeButtonHandler,
    changeHttpsAuthenticationUserCredentialsInputHandler,
    formVcsRepositoryAuthenticationSubmitHandler,
    changeVcsProtocolRadioButtonHandler,
  } = useVcsAnyRepositoryAuthenticationForm(
    projectId,
    onSumbit,
    onChangeHttpsAuthType,
    onChangeVcsProtocol,
    vcsProtocol,
    httpsAuthType,
    url,
    username,
    password,
  )
  const isVcsProtocolSsh = vcsProtocol === ProtocolVcsRepository.SSH
  const classNameForm = cn({
    [styles.formInputEmptyError]: isRepositoryTestConnectionError,
    [styles.formCompact]: compact,
  })

  return (
    <div className={classNameForm}>
      <SlideInOutAnimation show={isShowVcsAnyRepositoryForm} mountOnEnter unmountOnExit>
        <div className={styles.inputGropup}>
          <div className={styles.inputGropupLabel} />
          <div className={cn(styles.protocolRadioGroup, styles.inputGropupControl)}>
            <Radio
              value={vcsProtocol}
              onChange={changeVcsProtocolRadioButtonHandler}
              disabled={disableChangingVcsProtocol}
            >
              {vcsAnyRepositoryProtocols.map(({name}) => (
                <Radio.Item key={name} title={name} name={name} value={name}>
                  {name}
                </Radio.Item>
              ))}
            </Radio>
          </div>
        </div>
        {isVcsProtocolSsh ? (
          <VcsSshRepositoryAuthenticationForm
            projectId={projectId}
            onSelectKeyName={changeSshAuthenticationKeyNameSelectHandle}
            onChangePassphrase={changeSshAuthenticationPassphraseInputHandler}
            keyName={sshAuthenticationUserCredentials?.name}
            passphrase={sshAuthenticationUserCredentials?.passphrase}
          />
        ) : (
          <VcsHttpsRepositoryAuthenticationForm
            compact={compact}
            authType={httpsAuthType}
            onChangeAuthType={changeHttpsAuthenticationAuthTypeButtonHandler}
            onChange={changeHttpsAuthenticationUserCredentialsInputHandler}
            username={httpsAuthenticationUserCredentials?.username}
            password={httpsAuthenticationUserCredentials?.password}
            usernameError={httpsAuthenticationFormError?.username}
            passwordError={httpsAuthenticationFormError?.password}
          />
        )}
      </SlideInOutAnimation>
      <VcsRepositoryAuthenticationFormFooter
        onClick={formVcsRepositoryAuthenticationSubmitHandler}
        compact={compact}
        loading={isRepositoryTestConnectionLoading}
        disabled={isProceedButtonDisabled}
        errorMessage={testConnectionErrorMessage}
        cancelButton={cancelButton}
      />
    </div>
  )
}

export default VcsAnyRepositoryAuthenticationForm
