import classNames from 'classnames'
import type {ReactNode} from 'react'
import {useRef} from 'react'
import {Transition} from 'react-transition-group'

import styles from './SlideInOutAnimation.module.css'

const DEFAULT_ANIMATION_DURATION = 400

type Props = {
  show?: boolean
  duration?: number
  children: ReactNode
  mountOnEnter?: boolean
  unmountOnExit?: boolean
  contentClassName?: string
}
function SlideInOutAnimation({
  children,
  contentClassName,
  show,
  mountOnEnter,
  unmountOnExit,
  duration = DEFAULT_ANIMATION_DURATION,
}: Props) {
  const ref = useRef(null)

  return (
    <Transition
      in={show}
      nodeRef={ref}
      timeout={duration}
      mountOnEnter={mountOnEnter}
      unmountOnExit={unmountOnExit}
    >
      {state => (
        <div
          className={classNames(
            styles.animationContainer,
            state === 'entering' || state === 'entered' ? styles.in : null,
          )}
          ref={ref}
          style={{
            transition: `opacity ${duration}ms, grid-template-rows ${duration}ms`,
          }}
        >
          <div className={contentClassName}>{children}</div>
        </div>
      )}
    </Transition>
  )
}

export default SlideInOutAnimation
