import Link from '@jetbrains/ring-ui-built/components/link/link'
import type {MouseEvent} from 'react'
import {memo} from 'react'

import {getVcsProviderLoginUrl, loginToVcsProvider} from '../../utils/vcs'

import type {ProjectId} from 'src/types'

type Props = {
  className?: string
  connectionId: string
  projectId?: ProjectId
  onLogin?: () => void
}
function VcsLoginLink({connectionId, className, onLogin, projectId}: Props) {
  const loginUrl = getVcsProviderLoginUrl(connectionId, projectId)
  const target = `vcs_${connectionId}`

  const handleLogin = (e: MouseEvent) => {
    e.stopPropagation()
    loginToVcsProvider(connectionId, projectId, onLogin)
  }

  return (
    <Link className={className} href={loginUrl} target={target} onClick={handleLogin}>
      {'Log in'}
    </Link>
  )
}

export default memo(VcsLoginLink)
