import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import Select from '@jetbrains/ring-ui-built/components/select/select'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import {memo} from 'react'

import type {VcsProvider} from '../../services/pipelinesApi.types'
import type {ProtocolVcsRepository} from '../VcsAnyRepositoryAuthenticationForm/VcsAnyRepositoryAuthenticationForm.consts'

import {useDefaultBranchSelect} from './DefaultBranchSelect.hooks'

import styles from './DefaultBranchSelect.module.css'

import MiddleEllipsis from 'src/components/common/MiddleEllipsis/MiddleEllipsis'
import type {ProjectId} from 'src/types'

type Props = {
  projectId?: ProjectId
  vcsProtocol?: ProtocolVcsRepository
  vcsProvider?: VcsProvider
  repoUrl?: string
  repoDefaultBranch?: string | null
  selected?: string | null
  onSelectBranch?: (branch: string) => void
  disabled?: boolean
}
function DefaultBranchSelect({
  projectId,
  vcsProvider,
  vcsProtocol,
  selected,
  onSelectBranch,
  repoUrl = '',
  repoDefaultBranch,
  disabled,
}: Props) {
  const {selectItems, handleSelect, handleClose, handleFilter, isFetching} = useDefaultBranchSelect(
    repoUrl,
    projectId,
    vcsProtocol,
    selected,
    vcsProvider,
    repoDefaultBranch,
    onSelectBranch,
    disabled,
  )

  return (
    <Select
      data={selectItems}
      loading={isFetching}
      loadingMessage={'Loading branches...'}
      type={Select.Type.CUSTOM}
      directions={[Directions.BOTTOM_RIGHT]}
      disabled={disabled}
      customAnchor={({wrapperProps, buttonProps, popup}) => {
        const selectedLabel = `${selected ?? ''} ${selected === repoDefaultBranch ? '(Default)' : ''}`
        const selectedItem = isFetching ? 'Loading' : selectedLabel

        return (
          <span {...wrapperProps}>
            <IconButton
              {...buttonProps}
              className={classNames(styles.branchSelect, {[styles.disabled]: disabled})}
              iconClassName={classNames({[styles.branchIcon]: !disabled})}
              loader={isFetching}
              icon="branches"
              dropdown
            >
              <MiddleEllipsis className={styles.text} tailLength={10}>
                {selectedItem}
              </MiddleEllipsis>
            </IconButton>
            {popup}
          </span>
        )
      }}
      filter={{
        placeholder: 'Search or type refs/...',
      }}
      onFilter={handleFilter}
      onSelect={handleSelect}
      onClose={handleClose}
    />
  )
}

export default memo(DefaultBranchSelect)
