import Button from '@jetbrains/ring-ui-built/components/button/button'
import ButtonGroup from '@jetbrains/ring-ui-built/components/button-group/button-group'
import Input, {Size} from '@jetbrains/ring-ui-built/components/input/input'
import cn from 'classnames'
import type {ReactNode} from 'react'
import {Fragment} from 'react'

import PasswordInput from '../../PasswordInput/PasswordInput'
import {HttpsRepositoryAuthType} from '../VcsAnyRepositoryAuthenticationForm.consts'
import styles from '../VcsAnyRepositoryAuthenticationForm.module.css'

import {vcsHttpsRepositoryAuthentications} from './VcsHttpsRepositoryAuthenticationForm.const'

type VcsHttpsRepositoryAuthenticationFormProps = {
  compact?: boolean
  onChangeAuthType: (authType: HttpsRepositoryAuthType) => void
  onChange?: (event: React.ChangeEvent<HTMLInputElement>) => void
  authType: HttpsRepositoryAuthType
  username?: string
  password?: string
  usernameError?: ReactNode | null | undefined
  passwordError?: ReactNode | null | undefined
}

function VcsHttpsRepositoryAuthenticationForm({
  compact,
  onChangeAuthType,
  authType,
  onChange,
  username,
  password,
  usernameError,
  passwordError,
}: VcsHttpsRepositoryAuthenticationFormProps) {
  const authenticationMethodLabel = compact ? 'Authentication method' : null
  const clickHttpsAuthenticationButtonHandler = (id: HttpsRepositoryAuthType) => () =>
    onChangeAuthType(id)

  return (
    <Fragment>
      <div className={styles.inputGropup}>
        <div className={styles.inputGropupLabel}>{authenticationMethodLabel}</div>
        <div className={styles.inputGropupControl}>
          <ButtonGroup
            className={cn({[styles.vcsAnyRepositoryAuthenticationsButtonGroup]: compact})}
          >
            {vcsHttpsRepositoryAuthentications.map(({id, name}) => (
              <Button
                key={id}
                onClick={clickHttpsAuthenticationButtonHandler(id)}
                active={id === authType}
              >
                {name}
              </Button>
            ))}
          </ButtonGroup>
        </div>
      </div>
      {authType === HttpsRepositoryAuthType.TOKEN && (
        <div className={styles.inputGropup}>
          <label htmlFor="access-token-input" className={styles.inputGropupLabel}>
            {'Access token'}
          </label>
          <div className={styles.inputGropupControl}>
            <PasswordInput
              onChange={onChange}
              value={password}
              name="password"
              data-imitate-password
              autoComplete="off"
              id="access-token-input"
              size={Size.FULL}
              showEyeButton={!!password}
              error={passwordError}
            />
          </div>
        </div>
      )}
      {authType === HttpsRepositoryAuthType.PASSWORD && (
        <Fragment>
          <div className={styles.inputGropup}>
            <label htmlFor="username-input" className={styles.inputGropupLabel}>
              {'Username'}
            </label>
            <div className={styles.inputGropupControl}>
              <Input
                onChange={onChange}
                value={username}
                name="username"
                id="username-input"
                size={Size.FULL}
                error={usernameError}
              />
            </div>
          </div>
          <div className={styles.inputGropup}>
            <label htmlFor="password-input" className={styles.inputGropupLabel}>
              {'Password'}
            </label>
            <div className={styles.inputGropupControl}>
              <PasswordInput
                onChange={onChange}
                value={password}
                name="password"
                id="password-input"
                type="text"
                data-imitate-password
                showEyeButton={!!password}
                autoComplete="off"
                size={Size.FULL}
                error={passwordError}
              />
            </div>
          </div>
        </Fragment>
      )}
    </Fragment>
  )
}

export default VcsHttpsRepositoryAuthenticationForm
