import {graphql} from 'react-relay'

export const query = graphql`
  query ExistingVcsRootSelectQuery($projectLocator: String!) {
    project(projectLocator: $projectLocator) {
      id
      name
      vcsRoots {
        vcsRoot {
          id
          name
          vcsName
        }
      }
      ancestorProjects {
        project {
          id
          name
          vcsRoots {
            vcsRoot {
              id
              name
              vcsName
            }
          }
        }
      }
    }
  }
`
