import Button from '@jetbrains/ring-ui-built/components/button/button'
import {Size} from '@jetbrains/ring-ui-built/components/input/input'
import Select from '@jetbrains/ring-ui-built/components/select/select'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import {memo} from 'react'

import type {VcsProvider} from '../../services/pipelinesApi.types'
import Tooltip from '../Tooltip/Tooltip'

import {useVcsProviderSelect} from './VcsProviderSelect.hooks'

import styles from './VcsProviderSelect.module.css'

import type {ProjectId} from 'src/types'

type Props = {
  vcsProviders: VcsProvider[]
  selected?: VcsProvider | null
  disabled?: boolean
  disableReason?: string | null
  onSelectProvider?: (vcsProvider: VcsProvider) => void
  projectId?: ProjectId
  onLogin?: () => void
}

function VcsProviderSelect({
  vcsProviders,
  selected,
  disabled,
  disableReason,
  onSelectProvider,
  projectId,
  onLogin,
}: Props) {
  const {selectedItem, selectItems, handleSelect} = useVcsProviderSelect(
    vcsProviders,
    selected,
    onSelectProvider,
    onLogin,
    projectId,
  )

  return (
    <Select
      type={Select.Type.CUSTOM}
      size={Size.FULL}
      selected={selectedItem}
      disabled={disabled}
      data={selectItems}
      customAnchor={({wrapperProps, buttonProps, popup}) => (
        <span {...wrapperProps}>
          <Tooltip title={disabled ? disableReason : null}>
            {selectedItem?.glyph ? (
              <IconButton
                {...buttonProps}
                className={classNames(styles.vcsSelect, {[styles.disabled]: disabled})}
                iconClassName={styles.vcsIcon}
                icon={selectedItem.glyph}
                title={''}
                withBorder
                dropdown
              >
                {selectedItem?.label}
              </IconButton>
            ) : (
              <Button
                {...buttonProps}
                className={classNames(styles.vcsSelect, {[styles.disabled]: disabled})}
                title={''}
                dropdown
              >
                {'Select VCS provider'}
              </Button>
            )}
          </Tooltip>
          {popup}
        </span>
      )}
      onSelect={handleSelect}
    />
  )
}

export default memo(VcsProviderSelect)
