import {useEffect, useMemo} from 'react'

import type {ExistingVcsRootFormQuery} from './__generated__/ExistingVcsRootFormQuery.graphql'
import {existingVcsRootFormQuery} from './ExistingVcsRootForm.queries'

import {useBackgroundQuery} from 'src/hooks/relay/useBackgroundQuery'
import {useDebounceValue} from 'src/hooks/useDebounceValue'

const STATE_DEBOUNCE = 500

export function useExistingVcsRootForm(vcsRootId?: string | null) {
  const [{data, isLoading}, fetchVcsRootProperties] =
    useBackgroundQuery<ExistingVcsRootFormQuery>(existingVcsRootFormQuery)

  const debouncedLoading = useDebounceValue(isLoading, STATE_DEBOUNCE)

  useEffect(() => {
    if (vcsRootId != null) {
      fetchVcsRootProperties({
        vcsRootLocator: `id:${vcsRootId}`,
      })
    }
  }, [vcsRootId, fetchVcsRootProperties])

  const properties = useMemo(() => {
    const properties = data?.vcsRoots?.vcsRoot?.[0]?.properties?.property

    return new Map(properties?.map(property => [property.name, property.value]))
  }, [data])

  return {
    isLoading: debouncedLoading || (data == null && vcsRootId != null),
    url: properties.get('url'),
    port: properties.get('port'),
    branch: properties.get('branch'),
    branchSpecification: properties.get('teamcity:branchSpec'),
  }
}
