import fuzzyHighlight from '@jetbrains/ring-ui-built/components/global/fuzzy-highlight'
import {IconButton, SvgIcon} from '@jetbrains/teamcity-ui/dist/components'

import type {VcsRepository} from '../../services/pipelinesApi.types'
import forkIcon from '../../svg/fork.svg'
import {getHttpsRepositoryUrlFromSsh, getRepositoryFullName} from '../../utils/vcs'

import {DEFAULT_PAGE_SIZE} from './RepositorySelect.consts'
import type {RepositorySelectItem} from './RepositorySelect.types'

import styles from './RepositorySelect.module.css'

import type {Match} from 'src/components/common/Highlight/Highlight'
import Highlight from 'src/components/common/Highlight/Highlight'

function getRepositorySelectItem(
  {htmlUrl, defaultBranch, description, isPrivate, isFork, repositoryName}: VcsRepository,
  matches = [] as Match[],
): RepositorySelectItem {
  const label = getRepositoryFullName(htmlUrl)

  return {
    key: htmlUrl,
    className: styles.repoItemButton,
    label: (
      <div className={styles.repoItem}>
        <div className={styles.nameRow}>
          {isPrivate && <SvgIcon className={styles.icon} icon="lock" />}
          <span className={styles.repoName}>
            <Highlight string={label} matches={matches} />
          </span>
          {isFork && <SvgIcon className={styles.icon} icon={forkIcon} />}
          <IconButton
            className={styles.repoLink}
            href={htmlUrl}
            childrenLeft
            target="_blank"
            rel="noreferrer"
            icon="new-window"
            onClick={e => e.stopPropagation()}
            inline
          >
            {'View'}
          </IconButton>
        </div>
        <span className={styles.repoDescription}>{description ?? 'No description'}</span>
      </div>
    ),
    selectedLabel: label,
    payload: {
      url: htmlUrl,
      name: repositoryName,
      defaultBranch,
      isPrivate,
    },
  }
}

export function getRepositorySelectItems(
  vcsRepositories: VcsRepository[],
  searchValue = '',
  isTestConnectionSuccess = false,
) {
  if (searchValue.length === 0) {
    return vcsRepositories.map(repo => getRepositorySelectItem(repo))
  }

  const fullRepoName = getRepositoryFullName(searchValue)
  const repositoriesWithScore = vcsRepositories
    .map(repo => {
      const {matches} = fuzzyHighlight(fullRepoName, getRepositoryFullName(repo.htmlUrl))
      const score = matches.reduce((maxMatch, match) => {
        const {from, to} = match
        const diff = to - from

        return diff > maxMatch ? diff : maxMatch
      }, 0)

      return {repo, score, matches}
    })
    .filter(({score}) => score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, DEFAULT_PAGE_SIZE)

  if (repositoriesWithScore.length === 0 && isTestConnectionSuccess) {
    return [
      getRepositorySelectItem({
        htmlUrl: getHttpsRepositoryUrlFromSsh(searchValue),
        defaultBranch: null,
        repositoryName: fullRepoName.split('/')[1],
        isPrivate: false,
      } as VcsRepository),
    ]
  }

  return repositoriesWithScore.map(({repo, matches}) => getRepositorySelectItem(repo, matches))
}
