import Select from '@jetbrains/ring-ui-built/components/select/select'
import type {SerializedError} from '@reduxjs/toolkit'
import type {FetchBaseQueryError} from '@reduxjs/toolkit/query'
import plur from 'plur'
import {memo, useCallback} from 'react'

import type {ProjectId} from '../../../../../types'
import type {VcsProvider, VcsRepository} from '../../services/pipelinesApi.types'
import {getRepositoryFullName} from '../../utils/vcs'
import Tooltip from '../Tooltip/Tooltip'

import {useRepositorySelect} from './RepositorySelect.hooks'
import type {SelectedRepository} from './RepositorySelect.types'

import styles from './RepositorySelect.module.css'

type Props = {
  projectId: ProjectId
  selected?: SelectedRepository | null
  vcsProvider?: VcsProvider
  onSelectRepository?: (repo: SelectedRepository | null) => void
  repositoryFilterFn?: (repo: VcsRepository[]) => VcsRepository[]
  autoFocus?: boolean
  disabled?: boolean
  disableReason?: string | null
  error?: string
  onError?: (error: FetchBaseQueryError | SerializedError | null) => void
}
function RepositorySelect({
  projectId,
  vcsProvider,
  selected,
  onSelectRepository,
  repositoryFilterFn,
  disabled,
  disableReason,
  autoFocus = false,
  error,
  onError,
}: Props) {
  const {
    inputRef,
    filterValue,
    selectItems,
    selectedItem,
    handleSelect,
    handleFilter,
    handleOpen,
    shouldShowLoader,
  } = useRepositorySelect(
    projectId,
    vcsProvider,
    selected,
    onSelectRepository,
    repositoryFilterFn,
    autoFocus,
    disabled,
    onError,
  )
  const filterRepositoryName = getRepositoryFullName(selected?.name ?? '')
  const renderFooter = useCallback(() => {
    if (
      filterValue !== '' ||
      shouldShowLoader ||
      selectItems.length === 0 ||
      selected?.name != null
    ) {
      return null
    }
    return (
      <div className={styles.footer}>
        {`Showing ${selectItems.length} ${plur('repositories', selectItems.length)}, search to view others.`}
      </div>
    )
  }, [filterValue, shouldShowLoader, selectItems, selected])

  return (
    <Tooltip title={disabled ? disableReason : null}>
      <Select
        className={styles.select}
        key={String(disabled)}
        selected={selectedItem}
        type={Select.Type.INPUT}
        size={Select.Size.FULL}
        inputPlaceholder={'Select or type repository URL'}
        data={selectItems}
        filterRef={inputRef}
        filter={{value: filterRepositoryName}}
        onSelect={handleSelect}
        onFilter={handleFilter}
        onOpen={handleOpen}
        label={''}
        error={error}
        loading={shouldShowLoader}
        notFoundMessage={'No repositories found'}
        loadingMessage={'Loading repositories...'}
        hideArrow
        allowAny
        disabled={disabled}
        renderBottomToolbar={renderFooter}
      />
    </Tooltip>
  )
}

export default memo(RepositorySelect)
