import {useMemo} from 'react'

import {useRefetchableLazyLoadQuery} from '../../../../hooks/relay/useRefetchableLazyLoadQuery'
import {useQueryParam} from '../../../../hooks/routes'
import {matchRoute, Routes} from '../../../../routes'
import {notNull} from '../../../../utils/guards'
import type {CreatePipelinePageQuery} from '../CreatePipelinePage/__generated__/CreatePipelinePageQuery.graphql'
import {
  existingVcsRootProvider,
  loginScreenModeProviders,
  vcsAddNewConnectionProvider,
  vcsAnyGitProvider,
} from '../CreatePipelinePage/CreatePipelinePage.consts'
import {createPipelinePageQuery} from '../CreatePipelinePage/CreatePipelinePage.queries'
import {getAuthorizedVcsProvider} from '../CreatePipelinePage/CreatePipelinePage.utils'
import {pipelinesApi} from '../services/pipelinesApi'
import {type VcsProvider, VcsProviderType} from '../services/pipelinesApi.types'
import {
  isPipelinesEnabledInExclusiveMode,
  isProjectsAndBuildTypesEnabled,
} from '../utils/featureToggles'

import type {ProjectId} from 'src/types'

function usePipelineVcsProviders(projectId?: ProjectId) {
  const createPipelinePageMode = useQueryParam('mode')
  const isLoginScreenMode = createPipelinePageMode === 'loginScreen'
  const {
    refetch: getVcsProvidersRefetch,
    mainVcsProviders,
    authorizedProvider,
  } = pipelinesApi.endpoints.getVcsProviders.useQuery(
    {parentProjectId: projectId},
    {
      refetchOnFocus: true,
      selectFromResult: ({data, isLoading, isFetching}) => ({
        mainVcsProviders: data,
        authorizedProvider: data ? getAuthorizedVcsProvider(data) : null,
        isLoadingVcsProviders: isLoading || isFetching,
      }),
    },
  )
  const [{project}, getRefetchVcsRoots] = useRefetchableLazyLoadQuery<CreatePipelinePageQuery>(
    createPipelinePageQuery,
    {
      skip: !isProjectsAndBuildTypesEnabled(),
      locator: `id:${projectId}`,
    },
  )
  const hasVcsRoots =
    Boolean(project?.vcsRoots?.count) ||
    project?.ancestorProjects?.project?.some(ancestorProject => ancestorProject.vcsRoots?.count)
  // Temparily solution for hide existing VCS root provider on Edit Pipeline screen
  const windowOpenerQueryParams = new URLSearchParams(window.opener?.location?.search)
  const isFromEditPipelineScreen = windowOpenerQueryParams.has('edit')
  const isCreatePipelineScreen = matchRoute(Routes.CREATE_PIPELINE, location.pathname)
  const vcsProviders: VcsProvider[] | null = useMemo(() => {
    if (mainVcsProviders) {
      const vcsRootProvider =
        isProjectsAndBuildTypesEnabled() && hasVcsRoots && isCreatePipelineScreen
          ? existingVcsRootProvider
          : null

      if (isLoginScreenMode) {
        return loginScreenModeProviders.filter(
          provider =>
            // Temparily solution for hide existing VCS root/Any provider on Edit Pipeline screen
            !(
              isFromEditPipelineScreen &&
              (provider.type === VcsProviderType.CONNECT_BY_REPOSITORY_URL ||
                provider.type === VcsProviderType.ANY)
            ),
        )
      }

      if (isPipelinesEnabledInExclusiveMode()) {
        return [
          ...mainVcsProviders.filter(
            provider =>
              provider.connectionId != null ||
              provider.type === VcsProviderType.ANY ||
              provider.type === VcsProviderType.EXISTING_VCS_ROOT,
          ),
          vcsAnyGitProvider,
        ]
      }

      return [
        ...mainVcsProviders.filter(provider => provider.connectionId != null),
        vcsRootProvider,
        vcsAnyGitProvider,
        vcsAddNewConnectionProvider,
      ].filter(notNull)
    }

    return null
  }, [
    isCreatePipelineScreen,
    isFromEditPipelineScreen,
    isLoginScreenMode,
    mainVcsProviders,
    hasVcsRoots,
  ])

  return {
    isLoginScreenMode,
    vcsProviders,
    authorizedProvider,
    getRefetchVcsRoots,
    getVcsProvidersRefetch,
  }
}

export default usePipelineVcsProviders
