import CheckmarkIcon from '@jetbrains/icons/checkmark-12px.svg'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import cn from 'classnames'

import type {ProtocolVcsRepository} from '../../VcsAnyRepositoryAuthenticationForm/VcsAnyRepositoryAuthenticationForm.consts'

import styles from './RepositoryEditUrl.module.css'

type RepositoryEditUrlProps = {
  vcsProtocol: ProtocolVcsRepository
  onClick: () => void
  className?: string
}

function RepositoryEditUrl({vcsProtocol, onClick, className}: RepositoryEditUrlProps) {
  const containerClassName = cn(styles.anyVcsProviderVerifiedLabel, className)

  return (
    <div className={containerClassName}>
      <CheckmarkIcon />
      {`Used ${vcsProtocol} for authentication.`}
      <Button onClick={onClick} className={styles.anyVcsProviderVerifiedLabelButton} inline>
        {'Edit authentication settings'}
      </Button>
    </div>
  )
}

export default RepositoryEditUrl
