import LockIcon from '@jetbrains/icons/lock.svg'
import {useCallback, useEffect, useMemo, useState} from 'react'

import type {ProjectId} from '../../../../../../types'
import {pipelinesApi} from '../../../services/pipelinesApi'

import type {SelectItemVcsSsh} from './VcsSshRepositoryAuthenticationForm.types'

const minSearchSshKeysLength = 10

function useVcsSshRepositoryAuthenticationForm(
  projectId: ProjectId,
  keyName: string,
  onSelectKeyName?: (value: SelectItemVcsSsh | null) => void,
) {
  const [isShowSshUploadDialog, setIsShowSshUploadDialog] = useState<boolean>(false)
  const clockUploadDialogOpenButtonHandler = () => setIsShowSshUploadDialog(true)
  const [getProjectSshKeys, {projectSshKeys, isProjectSshKeysLoading}] =
    pipelinesApi.endpoints.getProjectSshKeys.useLazyQuery({
      selectFromResult: ({data, isLoading, isFetching}) => ({
        projectSshKeys: data?.sshKey ?? [],
        isProjectSshKeysLoading: isLoading || isFetching,
      }),
    })
  const loadProjectSshKeys = useCallback(
    async () =>
      await getProjectSshKeys({
        projectId,
      }),
    [getProjectSshKeys, projectId],
  )
  const projectSshKeysSelectItems = useMemo(
    () =>
      projectSshKeys.map<SelectItemVcsSsh>(({name, encrypted}) => ({
        encrypted,
        label: name,
        key: name,
        rightGlyph: encrypted ? LockIcon : null,
      })),
    [projectSshKeys],
  )
  const clickUploadDialogCloseButtonHandler = useCallback(
    async (value?: string) => {
      await loadProjectSshKeys()
      setIsShowSshUploadDialog(false)

      if (value) {
        onSelectKeyName?.({
          label: value,
          key: value,
          encrypted: false,
        })
      }
    },
    [loadProjectSshKeys, onSelectKeyName],
  )
  const projectSshKeysSelectedValue = useMemo(
    () => projectSshKeysSelectItems.find(({key}) => key === keyName),
    [keyName, projectSshKeysSelectItems],
  )
  const isShowSelectDropdownFilter = projectSshKeysSelectItems.length > minSearchSshKeysLength
  const selectDropdownFilterOptions = useMemo(
    () => (isShowSelectDropdownFilter ? {placeholder: 'Search key'} : false),
    [isShowSelectDropdownFilter],
  )

  useEffect(() => {
    loadProjectSshKeys()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  return {
    isProjectSshKeysLoading,
    projectSshKeysSelectItems,
    isShowSshUploadDialog,
    selectDropdownFilterOptions,
    projectSshKeysSelectedValue,
    clockUploadDialogOpenButtonHandler,
    clickUploadDialogCloseButtonHandler,
  }
}

export default useVcsSshRepositoryAuthenticationForm
