import type {SelectItem} from '@jetbrains/ring-ui-built/components/select/select'
import {useEffect, useMemo, useState} from 'react'

import {pipelinesApi} from '../../services/pipelinesApi'
import type {VcsProvider} from '../../services/pipelinesApi.types'
import {VcsProviderType} from '../../services/pipelinesApi.types'
import {ProtocolVcsRepository} from '../VcsAnyRepositoryAuthenticationForm/VcsAnyRepositoryAuthenticationForm.consts'

import {branchNameDefault, defaultBranches} from './DefaultBranchSelect.consts'
import {getDefaultBranchSelectItems} from './DefaultBranchSelect.utils'

import {useDebounceValue} from 'src/hooks/useDebounceValue'
import type {ProjectId} from 'src/types'

const SEARCH_DEBOUNCE = 500

export function useDefaultBranchSelect(
  repoUrl: string,
  projectId?: ProjectId,
  vcsProtocol?: ProtocolVcsRepository,
  selected?: string | null,
  vcsProvider?: VcsProvider,
  repoDefaultBranch?: string | null,
  onSelectBranch?: (branch: string) => void,
  disabled?: boolean,
) {
  const isAnyGit = vcsProvider?.type === VcsProviderType.ANY
  const isSshProtocol = vcsProtocol === ProtocolVcsRepository.SSH
  const repositoryBranchesRequestData = useMemo(() => {
    const {username, connectionId, password} = vcsProvider ?? {}
    const params = {
      connectionId,
      url: repoUrl,
      parentProjectId: projectId,
    }
    if (isSshProtocol && isAnyGit) {
      return {
        ...params,
        sshKey: {
          name: username,
          passphrase: password,
        },
      }
    }

    return {
      ...params,
      username,
      password,
    }
  }, [isAnyGit, isSshProtocol, repoUrl, vcsProvider, projectId])
  const {branches, isBranchesFetchingError, isFetching} =
    pipelinesApi.endpoints.getRepositoryBranches.useQuery(repositoryBranchesRequestData, {
      selectFromResult: ({currentData, isError, isFetching}) => ({
        branches: currentData,
        isBranchesFetchingError: isError,
        isFetching,
      }),
      skip: disabled || repoUrl.length === 0 || vcsProvider == null,
      refetchOnMountOrArgChange: 30,
    })
  const [searchValue, setSearchValue] = useState('')
  const deferredSearch = useDebounceValue(searchValue, SEARCH_DEBOUNCE)
  const selectItems = useMemo(
    () => getDefaultBranchSelectItems(branches ?? [], repoDefaultBranch, deferredSearch),
    [branches, deferredSearch, repoDefaultBranch],
  )
  const handleSelect = (value: SelectItem | null) => {
    if (value?.selectedLabel != null) {
      onSelectBranch?.(value.selectedLabel.replaceAll(' ', ''))
    }
  }
  const handleClose = () => setSearchValue('')
  const handleFilter = (value: string) => setSearchValue(value.trim())

  // xx
  useEffect(() => {
    if (!selected && branches) {
      const defaultBranch =
        branches.find(branch => defaultBranches.has(branch)) ?? branchNameDefault
      onSelectBranch?.(defaultBranch)
    } else if (!selected && isBranchesFetchingError) {
      onSelectBranch?.(branchNameDefault)
    }
  }, [branches, isBranchesFetchingError, onSelectBranch, selected])

  return {
    selectItems,
    handleSelect,
    handleClose,
    handleFilter,
    isFetching,
  }
}
