import type {ToggleAttrs} from '@jetbrains/ring-ui-built/components/toggle/toggle'
import Toggle from '@jetbrains/ring-ui-built/components/toggle/toggle'

import styles from './PublishStatusToggle.module.css'

import HelpDetails from 'src/components/common/HelpDetails/HelpDetails'
import SwitcherLabel from 'src/components/common/SwitcherLabel/SwitcherLabel'

type Props = {
  checked?: boolean
  onToggle?: ToggleAttrs['onChange']
}
function PublishStatusToggle({checked, onToggle}: Props) {
  const isToggleEnabled = onToggle != null

  const toggleContent = (
    <>
      {!isToggleEnabled && <SwitcherLabel className={styles.label} on={checked} />}
      {'Publish status to repository'}
      <HelpDetails acnhorClassName={styles.info}>
        {'TeamCity Pipelines automatically sends build statuses of your commits to your VCS'}
      </HelpDetails>
    </>
  )

  return isToggleEnabled ? (
    <Toggle checked={checked} onChange={onToggle}>
      {toggleContent}
    </Toggle>
  ) : (
    <div>{toggleContent}</div>
  )
}

export default PublishStatusToggle
