import 'core-js/modules/es.array.to-sorted' // https://github.com/Fyrd/caniuse/issues/6670
import fuzzyHighlight from '@jetbrains/ring-ui-built/components/global/fuzzy-highlight'
import type {SelectItem} from '@jetbrains/ring-ui-built/components/select/select'

import type {Match} from 'src/components/common/Highlight/Highlight'
import Highlight from 'src/components/common/Highlight/Highlight'

function getDefaultBranchSelectItem(
  branch: string,
  repoDefaultBranch?: string | null,
  matches = [] as Match[],
): SelectItem {
  return {
    key: branch,
    selectedLabel: branch,
    description: branch === repoDefaultBranch ? 'Default' : null,
    label: <Highlight string={branch} matches={matches} />,
  }
}

const DEFAULT_PAGE_SIZE = 10

export function getDefaultBranchSelectItems(
  branches: string[],
  repoDefaultBranch?: string | null,
  searchValue = '',
) {
  if (searchValue.length === 0) {
    return (
      branches
        // show default branch in the beginning of the list
        .toSorted((a, b) => (a === repoDefaultBranch ? -1 : b === repoDefaultBranch ? 1 : 0))
        .map(branch => getDefaultBranchSelectItem(branch, repoDefaultBranch))
    )
  }

  const branchesWithScore = branches
    .map(branch => {
      const {matches} = fuzzyHighlight(searchValue, branch)
      const score = matches.reduce((maxMatch, match) => {
        const {from, to} = match
        const diff = to - from

        return diff > maxMatch ? diff : maxMatch
      }, 0)

      return {branch, matches, score}
    })
    .filter(({score}) => score > 0)
    .sort((a, b) =>
      a.branch === searchValue ? -1 : b.branch === searchValue ? 1 : b.score - a.score,
    )
    .slice(0, DEFAULT_PAGE_SIZE)

  if (branchesWithScore.length === 0) {
    return [getDefaultBranchSelectItem(searchValue)]
  }

  return branchesWithScore.map(({branch, matches}) =>
    getDefaultBranchSelectItem(branch, repoDefaultBranch, matches),
  )
}
