import type {SerializedError} from '@reduxjs/toolkit'
import type {FetchBaseQueryError} from '@reduxjs/toolkit/query'
import {useEffect, useMemo, useRef, useState} from 'react'

import type {ProjectId} from '../../../../../types'
import {pipelinesApi} from '../../services/pipelinesApi'
import type {VcsProvider, VcsRepository} from '../../services/pipelinesApi.types'
import {VcsProviderCapability} from '../../services/pipelinesApi.types'
import {
  getHttpsRepositoryUrlFromSsh,
  getRepositoryFullName,
  verifyRepositoryUrl,
} from '../../utils/vcs'

import {SEARCH_DEBOUNCE, DEFAULT_PAGE_SIZE} from './RepositorySelect.consts'
import type {RepositorySelectItem, SelectedRepository} from './RepositorySelect.types'
import {getRepositorySelectItems} from './RepositorySelect.utils'

import {useDebounceValue} from 'src/hooks/useDebounceValue'
import {emptyArray, noop} from 'src/utils/empty'

const focusWaitTimeOut = 300

export function useRepositorySelect(
  projectId?: ProjectId,
  vcsProvider?: VcsProvider,
  selected?: SelectedRepository | null,
  onSelectRepository?: (repo: SelectedRepository | null) => void,
  repositoryFilterFn?: (repo: VcsRepository[]) => VcsRepository[],
  autoFocus?: boolean,
  disabled?: boolean,
  onError?: (error: FetchBaseQueryError | SerializedError | null) => void,
) {
  const [searchValue, setSearchValue] = useState('')
  const [filterValue, setFilterValue] = useState('')
  const deferredSearch = useDebounceValue(searchValue, SEARCH_DEBOUNCE)
  const isSearchMode = deferredSearch.length > 0
  const {isServerSearchSupported, isPaginationSupported, isPageSizeSupported} = useMemo(() => {
    const capabilities = new Set(vcsProvider?.capabilities ?? [])
    const isServerSearchSupported = capabilities.has(VcsProviderCapability.REPOS_SEARCH)
    const isPaginationSupported =
      isServerSearchSupported && capabilities.has(VcsProviderCapability.REPOS_PAGING)
    const isPageSizeSupported =
      isPaginationSupported && capabilities.has(VcsProviderCapability.REPOS_PAGE_SIZE)
    return {
      isServerSearchSupported,
      isPaginationSupported,
      isPageSizeSupported,
    }
  }, [vcsProvider?.capabilities])
  const {rawRepositories, areRepositoriesFetching, error, refetch} =
    pipelinesApi.endpoints.getRepositories.useQuery(
      {
        parentProjectId: projectId,
        connectionId: vcsProvider?.connectionId ?? '',
        q:
          isServerSearchSupported && isSearchMode
            ? getRepositoryFullName(deferredSearch)
            : undefined,
        page: isPaginationSupported ? 0 : undefined,
        pageSize: isPageSizeSupported ? DEFAULT_PAGE_SIZE : undefined,
      },
      {
        selectFromResult: ({currentData, isFetching, error}) => ({
          rawRepositories: currentData?.values,
          error,
          areRepositoriesFetching: isFetching,
        }),
        refetchOnMountOrArgChange: 30,
        skip: !vcsProvider?.connectionId,
      },
    )

  useEffect(() => {
    if (onError != null && error != null) {
      onError(error)
    }
  }, [error, onError])

  const repositories = useMemo(
    () => repositoryFilterFn?.(rawRepositories ?? []) ?? rawRepositories,
    [rawRepositories, repositoryFilterFn],
  )

  const [isTestConnectionSuccess, setIsTestConnectionSuccess] = useState(false)
  const [testConnection, {isTestingConnection}] =
    pipelinesApi.endpoints.repositoryTestConnection.useMutation({
      selectFromResult: ({isLoading}) => ({
        isTestingConnection: isLoading,
      }),
    })

  const selectItems = useMemo(() => {
    if (repositories == null) {
      return emptyArray as RepositorySelectItem[]
    }
    return getRepositorySelectItems(repositories, deferredSearch, isTestConnectionSuccess)
  }, [repositories, deferredSearch, isTestConnectionSuccess])

  const selectedItem = useMemo(
    () => selectItems.find(repo => repo.payload.url === selected?.url),
    [selectItems, selected],
  )

  const inputRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    if (autoFocus && !disabled) {
      setTimeout(() => {
        inputRef.current?.focus()
        inputRef.current?.click()
      }, focusWaitTimeOut)
    }
  }, [autoFocus, disabled, vcsProvider])

  useEffect(() => {
    if (deferredSearch.length === 0) {
      return
    }

    const url = getHttpsRepositoryUrlFromSsh(deferredSearch)
    if (rawRepositories != null && selectItems.length === 0 && verifyRepositoryUrl(url)) {
      testConnection({
        parentProjectId: projectId,
        body: {
          url,
          connectionId: vcsProvider?.connectionId,
          vcsName: 'jetbrains.git', // TODO Why do we use hardcoded vcsName?
        },
      })
        .unwrap()
        .then(({status}) => {
          if (status === 'OK') {
            setIsTestConnectionSuccess(true)
          }
        })
        .catch(noop)
    }
  }, [
    deferredSearch,
    selectItems,
    rawRepositories,
    testConnection,
    vcsProvider?.connectionId,
    projectId,
  ])

  useEffect(() => {
    setIsTestConnectionSuccess(false)
  }, [deferredSearch])

  const handleSelect = (newSelected: RepositorySelectItem | null) => {
    if (typeof newSelected?.key === 'number' && newSelected.label != null) {
      const inputValue = newSelected.label.toString().trim()
      setSearchValue(inputValue)
      onSelectRepository?.(null)
      return
    }
    if (newSelected != null) {
      onSelectRepository?.(newSelected.payload)
      setSearchValue('')
    }
  }

  const handleFilter = (value: string) => {
    setFilterValue(value)
  }

  const handleOpen = () => {
    if (error != null) {
      refetch()
    }
  }

  return {
    inputRef,
    filterValue,
    selectItems,
    selectedItem,
    handleSelect,
    handleFilter,
    handleOpen,
    shouldShowLoader: areRepositoriesFetching || isTestingConnection,
  }
}
