import {useState} from 'react'

import type {SelectItemVcsSsh} from './VcsSshRepositoryAuthenticationForm/VcsSshRepositoryAuthenticationForm.types'

type SshAuthenticationUserCredentials = {
  name: string
  passphrase?: string
  encrypted?: boolean
}

function useVcsSshAuthentication(
  repositoryTestConnectionReset: () => void,
  providerName?: string | null,
  providerPassword?: string | null,
) {
  const [sshAuthenticationUserCredentials, setSshAuthenticationUserCredentials] =
    useState<SshAuthenticationUserCredentials>({
      name: providerName ?? '',
      passphrase: providerPassword ?? '',
    })
  const changeSshAuthenticationPassphraseInputHandler = ({
    target,
  }: React.ChangeEvent<HTMLInputElement>) => {
    setSshAuthenticationUserCredentials({
      ...sshAuthenticationUserCredentials,
      passphrase: target.value,
    })
    repositoryTestConnectionReset()
  }
  const changeSshAuthenticationKeyNameSelectHandle = (value: SelectItemVcsSsh | null) => {
    if (value != null) {
      setSshAuthenticationUserCredentials({
        ...sshAuthenticationUserCredentials,
        name: `${value.key}`,
        passphrase: undefined,
        encrypted: value.encrypted,
      })
    }
    repositoryTestConnectionReset()
  }
  const isSshAuthenticationUserCredentialsNotReady =
    !sshAuthenticationUserCredentials.name ||
    (sshAuthenticationUserCredentials.encrypted && !sshAuthenticationUserCredentials.passphrase)

  return {
    sshAuthenticationUserCredentials,
    isSshAuthenticationUserCredentialsNotReady,
    changeSshAuthenticationKeyNameSelectHandle,
    changeSshAuthenticationPassphraseInputHandler,
  }
}

export default useVcsSshAuthentication
