import {Type as ListItemType} from '@jetbrains/ring-ui-built/components/list/consts'

import type {VcsProvider} from '../../services/pipelinesApi.types'
import {VcsProviderType} from '../../services/pipelinesApi.types'
import VcsLoginLink from '../VcsLoginLink/VcsLoginLink'
import {VcsProviderIconMap} from '../VcsProviderIcon/VcsProviderIcon.consts'

import type {VcsProviderSelectItem} from './VcsProviderSelect.types'

import styles from './VcsProviderSelect.module.css'

import GitIcon from 'src/components/common/GitIcon/GitIcon'
import type {ProjectId} from 'src/types'

const listItemAnySeparatorkey = 'SEPARATOR-ANY'

export const getSelectVcsProvider =
  (projectId?: ProjectId, onLogin?: () => void) =>
  (accumulator: VcsProviderSelectItem[], vcsProvider: VcsProvider, index: number) => {
    const {type} = vcsProvider
    const vcsProviderSelectItem = getVcsProviderSelectItem(vcsProvider, projectId, onLogin)
    const isFirstItem = index === 0
    const isAnyProvider = type === VcsProviderType.ANY
    const isAddNewConnectionProvider = type === VcsProviderType.NEW_CONNECTION
    const isConnectByRepositoryUrlProvider = type === VcsProviderType.EXISTING_VCS_ROOT
    const hasAnySeparator = accumulator.some(({key}) =>
      `${key}`.startsWith(listItemAnySeparatorkey),
    )

    if (
      isAddNewConnectionProvider ||
      ((isAnyProvider || isConnectByRepositoryUrlProvider) && !hasAnySeparator && !isFirstItem)
    ) {
      accumulator.push({
        key: `${listItemAnySeparatorkey}-${vcsProvider.type}`,
        rgItemType: ListItemType.SEPARATOR,
        payload: {},
      })
    }

    accumulator.push(vcsProviderSelectItem)

    return accumulator
  }

function getVcsProviderSelectItem(
  vcsProvider: VcsProvider,
  projectId?: ProjectId,
  onLogin?: () => void,
): VcsProviderSelectItem {
  const {connectionId, displayName, type, username} = vcsProvider
  const glyph = type && type in VcsProviderIconMap ? VcsProviderIconMap[type] : GitIcon
  const description =
    connectionId != null
      ? (username ?? (
          <VcsLoginLink connectionId={connectionId} projectId={projectId} onLogin={onLogin} />
        ))
      : null
  const isAddNewConnectionProvider = type === VcsProviderType.NEW_CONNECTION
  const className = isAddNewConnectionProvider ? styles.addNewConnection : styles.vcsSelectItem

  return {
    glyph,
    description,
    className,
    key: connectionId ?? `provider-${type}`,
    label: displayName,
    payload: vcsProvider,
  }
}
