import type {ChangeEvent} from 'react'
import {useEffect, useState} from 'react'

import {
  allBranchesSpecification,
  BranchSpecificationPolicy,
} from './BranchSpecificationSelect.consts'
import {getDefaultBranchSpecification} from './BranchSpecificationSelect.utils'

export function useBranchSpecificationSelect(
  specification: string,
  defaultBranch?: string | null,
  allBranches?: string,
  disabled?: boolean,
  onSelectSpecification?: (spec: string) => void,
  onToggleBranches?: (value: boolean) => void,
  onTogglePullRequests?: (value: boolean) => void,
) {
  const defaultBranchSpec = getDefaultBranchSpecification(defaultBranch)
  const allBranchesSpec = allBranches ?? allBranchesSpecification
  const [shouldShowExamples, setShouldShowExamples] = useState(false)
  const [specificationInputValue, setSpecificationInputValue] = useState<string | undefined>()

  useEffect(() => {
    if (specification !== allBranchesSpec && specification !== defaultBranchSpec) {
      setSpecificationInputValue(specification)
    } else {
      setSpecificationInputValue(undefined)
    }
  }, [specification, allBranchesSpec, defaultBranchSpec])
  const [specificationPolicy, setSpecificationPolicy] = useState(
    BranchSpecificationPolicy.ALL_BRANCHES,
  )
  useEffect(() => {
    if (specification === allBranchesSpec) {
      setSpecificationPolicy(BranchSpecificationPolicy.ALL_BRANCHES)
    } else if (specification === defaultBranchSpec) {
      setSpecificationPolicy(BranchSpecificationPolicy.DEFAULT_ONLY)
    } else {
      setSpecificationPolicy(BranchSpecificationPolicy.SPECIFIC)
    }
  }, [specification, defaultBranchSpec, allBranchesSpec])

  const handleChangePolicy = (value: string) => {
    if (value === BranchSpecificationPolicy.ALL_BRANCHES) {
      onSelectSpecification?.(allBranchesSpec)
    } else if (value === BranchSpecificationPolicy.DEFAULT_ONLY) {
      onSelectSpecification?.(defaultBranchSpec)
    } else if (value === BranchSpecificationPolicy.SPECIFIC) {
      if (specificationInputValue) {
        onSelectSpecification?.(specificationInputValue)
      }
    }
    setSpecificationPolicy(value as BranchSpecificationPolicy)
  }

  const handleShowExamples = () => setShouldShowExamples(!shouldShowExamples)

  const handleSpecificationInputChange = (e: ChangeEvent<HTMLTextAreaElement>) => {
    const value = e.currentTarget.value
    onSelectSpecification?.(value.trim())
    setSpecificationInputValue(value)
  }

  const handleToggleBranches = ({currentTarget}: ChangeEvent<HTMLInputElement>) => {
    onToggleBranches?.(currentTarget.checked)
  }

  const handleTogglePullRequests = ({currentTarget}: ChangeEvent<HTMLInputElement>) => {
    onTogglePullRequests?.(currentTarget.checked)
  }

  useEffect(() => {
    if (!disabled && specificationPolicy === BranchSpecificationPolicy.DEFAULT_ONLY) {
      onSelectSpecification?.(defaultBranchSpec)
    }
  }, [defaultBranchSpec, onSelectSpecification, specificationPolicy, disabled])

  return {
    specificationPolicy,
    handleChangePolicy,
    shouldShowExamples,
    handleShowExamples,
    specificationInputValue,
    handleSpecificationInputChange,
    handleToggleBranches,
    handleTogglePullRequests,
  }
}
