import 'core-js/modules/es.array.to-reversed' // https://github.com/Fyrd/caniuse/issues/6670
import VcsRootIcon from '@jetbrains/icons/vcs-root.svg'
import fuzzyHighlight from '@jetbrains/ring-ui-built/components/global/fuzzy-highlight'
import {Type as ListItemType} from '@jetbrains/ring-ui-built/components/list/consts'
import type {SelectItem} from '@jetbrains/ring-ui-built/components/select/select'

import {getAccountRootProjectId} from '../../PipelinesPages.consts'
import {getIsGitVcsRoot} from '../../utils/getIsGitVcsRoot'

import type {ExistingVcsRootSelectQuery$data} from './__generated__/ExistingVcsRootSelectQuery.graphql'

import styles from './ExistingVcsRootSelect.module.css'

import GitIcon from 'src/components/common/GitIcon/GitIcon'

type VcsRootSelectItem = SelectItem<{vcsName?: string | null}>

export function getVcsRootSelectItems(
  data: ExistingVcsRootSelectQuery$data,
  createdRepositories?: Set<string>,
): VcsRootSelectItem[] {
  const items = [] as VcsRootSelectItem[]
  const project = data?.project

  if (project == null) {
    return []
  }

  const ancestorProjects = project.ancestorProjects?.project
  const ancestorNames =
    ancestorProjects
      ?.filter(ancestorProject => ancestorProject.id !== getAccountRootProjectId())
      .map(ancestorProject => ancestorProject.name!) ?? []
  const vcsRoots = (project?.vcsRoots?.vcsRoot ?? []).filter(
    ({name}) => !createdRepositories?.has(`${name}`),
  )

  if (vcsRoots.length > 0) {
    const projectPath = ancestorNames.concat(project.name!).join(' / ')
    items.push({
      key: project.id!,
      label: (
        <span className={styles.projectName} title={projectPath}>
          {projectPath}
        </span>
      ),
      rgItemType: ListItemType.TITLE,
    })
    vcsRoots.forEach(vcsRoot => {
      items.push({
        key: vcsRoot.id!,
        label: vcsRoot.name!,
        // temp solution
        glyph: getIsGitVcsRoot(vcsRoot.vcsName) ? GitIcon : VcsRootIcon,
        vcsName: vcsRoot.vcsName,
      })
    })
  }

  ancestorProjects?.toReversed().forEach(ancestorProject => {
    ancestorNames.pop()
    const ancestorVcsRoots = ancestorProject?.vcsRoots?.vcsRoot ?? []
    if (ancestorVcsRoots.length === 0) {
      return
    }

    const ancestorPath =
      ancestorProject.id === getAccountRootProjectId()
        ? '<Root project>'
        : ancestorNames.concat(ancestorProject.name!).join(' / ')
    items.push({
      key: ancestorProject.id!,
      label: (
        <span className={styles.projectName} title={ancestorPath}>
          {ancestorPath}
        </span>
      ),
      rgItemType: ListItemType.TITLE,
    })
    ancestorVcsRoots.forEach(vcsRoot => {
      items.push({
        key: vcsRoot.id!,
        label: vcsRoot.name!,
        // temp solution
        glyph: getIsGitVcsRoot(vcsRoot.vcsName) ? GitIcon : VcsRootIcon,
        vcsName: vcsRoot.vcsName,
      })
    })
  })

  return items
}

export function getFilteredVcsRootSelectItems(selectItems: SelectItem[], filter: string) {
  if (filter.length === 0) {
    return selectItems
  }

  const result: SelectItem[] = []
  let currentTitleElement: SelectItem | null = null

  selectItems.forEach(item => {
    if (item.rgItemType === ListItemType.TITLE) {
      currentTitleElement = item
      return
    }

    if (item.label && fuzzyHighlight(filter, item.label.toString()).matched) {
      if (currentTitleElement != null) {
        result.push(currentTitleElement)
        currentTitleElement = null
      }
      result.push(item)
    }
  })

  return result
}
