import {useState} from 'react'

import {HttpsRepositoryAuthType} from './VcsAnyRepositoryAuthenticationForm.consts'
import type {VcsAnyRepositoryUserCredentials} from './VcsAnyRepositoryAuthenticationForm.types'
import {emptyInputFieldErrorMessage} from './VcsHttpsRepositoryAuthenticationForm/VcsHttpsRepositoryAuthenticationForm.const'

const defaulttHttpsUserCredentials = {
  username: '',
  password: '',
}

function useVcsHttpsAuthentication(
  authType: HttpsRepositoryAuthType,
  onChangeAuthType: (value: HttpsRepositoryAuthType) => void,
  repositoryTestConnectionReset: () => void,
  providerUsername?: string | null,
  providerPassword?: string | null,
) {
  const [httpsAuthenticationFormError, setHttpsAuthenticationFormError] =
    useState<Partial<VcsAnyRepositoryUserCredentials> | null>(null)
  const [httpsAuthenticationUserCredentials, setHttpsAuthenticationCredentials] =
    useState<VcsAnyRepositoryUserCredentials>({
      username: providerUsername ?? '',
      password: providerPassword ?? '',
    })
  const getHttpsAuthenticationFormErrors = () => {
    const inputErrors = new Map<keyof VcsAnyRepositoryUserCredentials, string>()
    const {password, username} = httpsAuthenticationUserCredentials

    if (authType !== HttpsRepositoryAuthType.ANONYMOUS && !password) {
      inputErrors.set('password', emptyInputFieldErrorMessage)
    }

    if (authType === HttpsRepositoryAuthType.PASSWORD && !username) {
      inputErrors.set('username', emptyInputFieldErrorMessage)
    }

    const errorsObject = inputErrors.size ? Object.fromEntries(inputErrors) : null

    setHttpsAuthenticationFormError(errorsObject)

    return errorsObject
  }
  const changeHttpsAuthenticationAuthTypeButtonHandler = (value: HttpsRepositoryAuthType) => {
    onChangeAuthType(value)
    repositoryTestConnectionReset()
    setHttpsAuthenticationFormError(null)

    if (
      httpsAuthenticationUserCredentials?.username ||
      httpsAuthenticationUserCredentials?.password
    ) {
      setHttpsAuthenticationCredentials(defaulttHttpsUserCredentials)
    }
  }
  const changeHttpsAuthenticationUserCredentialsInputHandler = ({
    target,
  }: React.ChangeEvent<HTMLInputElement>) => {
    const targetValue = target.value.trim()
    const value = targetValue ? targetValue : undefined

    setHttpsAuthenticationCredentials({...httpsAuthenticationUserCredentials, [target.name]: value})
    repositoryTestConnectionReset()
    setHttpsAuthenticationFormError(null)
  }

  return {
    httpsAuthenticationFormError,
    httpsAuthenticationUserCredentials,
    getHttpsAuthenticationFormErrors,
    changeHttpsAuthenticationAuthTypeButtonHandler,
    changeHttpsAuthenticationUserCredentialsInputHandler,
  }
}

export default useVcsHttpsAuthentication
