import {useEffect, useMemo} from 'react'

import type {ProjectId} from '../../../../../types'

import useRepositoryTestConnection from './useRepositoryTestConnection'
import useVcsHttpsAuthentication from './useVcsHttpsAuthentication'
import useVcsSshAuthentication from './useVcsSshAuthentication'
import {
  HttpsRepositoryAuthType,
  ProtocolVcsRepository,
} from './VcsAnyRepositoryAuthenticationForm.consts'

function useVcsAnyRepositoryAuthenticationForm(
  projectId: ProjectId,
  onSumbit: (isPrivate: boolean, username?: string, password?: string) => void,
  onChangeHttpsAuthType: (value: HttpsRepositoryAuthType) => void,
  onChangeVcsProtocol: (value: ProtocolVcsRepository) => void,
  vcsProtocol: ProtocolVcsRepository,
  httpsAuthType: HttpsRepositoryAuthType,
  url?: string,
  providerName?: string | null,
  providerPassword?: string | null,
) {
  const {
    repositoryTestConnectionError,
    isRepositoryTestConnectionError,
    isRepositoryTestConnectionLoading,
    repositoryTestConnection,
    repositoryTestConnectionReset,
  } = useRepositoryTestConnection()
  const {
    httpsAuthenticationFormError,
    httpsAuthenticationUserCredentials,
    getHttpsAuthenticationFormErrors,
    changeHttpsAuthenticationAuthTypeButtonHandler,
    changeHttpsAuthenticationUserCredentialsInputHandler,
  } = useVcsHttpsAuthentication(
    httpsAuthType,
    onChangeHttpsAuthType,
    repositoryTestConnectionReset,
    providerName,
    providerPassword,
  )
  const {
    sshAuthenticationUserCredentials,
    isSshAuthenticationUserCredentialsNotReady,
    changeSshAuthenticationKeyNameSelectHandle,
    changeSshAuthenticationPassphraseInputHandler,
  } = useVcsSshAuthentication(repositoryTestConnectionReset, providerName, providerPassword)
  const formVcsRepositoryAuthenticationSubmitHandler = async (
    event: React.FormEvent<HTMLButtonElement>,
  ) => {
    event.preventDefault()

    if (vcsProtocol === ProtocolVcsRepository.SSH) {
      const {name, passphrase} = sshAuthenticationUserCredentials

      if (name && url) {
        const {data} = await repositoryTestConnection({
          parentProjectId: projectId,
          body: {
            url,
            sshKey: sshAuthenticationUserCredentials,
          },
        })
        const isStatusOK = data?.status === 'OK'

        if (isStatusOK) {
          onSumbit(true, name, passphrase)
        }
      }
    } else if (vcsProtocol === ProtocolVcsRepository.HTTPS) {
      const httpsAuthenticationFormErrors = getHttpsAuthenticationFormErrors()

      if (url && !httpsAuthenticationFormErrors) {
        const {data} = await repositoryTestConnection({
          parentProjectId: projectId,
          body: {url, ...httpsAuthenticationUserCredentials},
        })
        const isStatusOK = data?.status === 'OK'

        if (isStatusOK) {
          const isPrivate = httpsAuthType !== HttpsRepositoryAuthType.ANONYMOUS

          onSumbit(
            isPrivate,
            httpsAuthenticationUserCredentials.username,
            httpsAuthenticationUserCredentials.password,
          )
        }
      }
    }
  }
  const isShowVcsAnyRepositoryForm = !!url
  const isProceedButtonDisabled = useMemo(() => {
    if (vcsProtocol === ProtocolVcsRepository.SSH) {
      return isSshAuthenticationUserCredentialsNotReady
    }

    if (vcsProtocol === ProtocolVcsRepository.HTTPS) {
      return !!httpsAuthenticationFormError
    }

    return !url
  }, [httpsAuthenticationFormError, isSshAuthenticationUserCredentialsNotReady, url, vcsProtocol])
  const testConnectionErrorMessage = repositoryTestConnectionError
    ?.map(({message}) => message)
    .join(' ')
  const changeVcsProtocolRadioButtonHandler = (value: string) => {
    const protocol = value as keyof typeof ProtocolVcsRepository

    onChangeVcsProtocol(ProtocolVcsRepository[protocol])
    repositoryTestConnectionReset()
  }

  useEffect(() => {
    if (isRepositoryTestConnectionError || testConnectionErrorMessage) {
      repositoryTestConnectionReset()
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [url])

  return {
    testConnectionErrorMessage,
    isRepositoryTestConnectionError,
    isProceedButtonDisabled,
    isShowVcsAnyRepositoryForm,
    isRepositoryTestConnectionLoading,
    httpsAuthenticationFormError,
    httpsAuthenticationUserCredentials,
    sshAuthenticationUserCredentials,
    changeSshAuthenticationKeyNameSelectHandle,
    changeSshAuthenticationPassphraseInputHandler,
    changeHttpsAuthenticationAuthTypeButtonHandler,
    changeHttpsAuthenticationUserCredentialsInputHandler,
    formVcsRepositoryAuthenticationSubmitHandler,
    changeVcsProtocolRadioButtonHandler,
  }
}

export default useVcsAnyRepositoryAuthenticationForm
